const FACES={tuck:['Front','Side','Top'],rsc:['Front','Side','Top'],custom:['Front','Side','Top'],mailer:['Lid','Side','Front'],tray:['Lid','Side'],bag:['Front','Gusset'],bcard:['Front','Back'],greeting:['Front','Inside'],leaflet:['Front','Back'],envelope:['Front','Back'],folder:['Front cover','Inside'],casewrap:['Front cover','Back'],letterhead:['Logo / header','Second piece'],digital:['Your design']};
