const DSZ=Object.entries(IT.digital.presets);
const slug=t=>String(t).replace(/×/g,'x').replace(/[^\w]+/g,'-').replace(/^-|-$/g,'').toLowerCase();
function sizesHtml(){const off=st.szoff||[];return`<h2>Export all sizes</h2><p class="note">Puts artwork 1 of this item into every size you tick and downloads one ZIP.</p><div class="szl">${DSZ.map(([n],i)=>`<label class="cb"><input type="checkbox" data-sz="${i}" ${off.includes(i)?'':'checked'}><span>${esc(n)}</span></label>`).join('')}</div><div class="ex"><button class="btn" data-x="szall">Tick all</button><button class="btn" data-x="sznone">Untick all</button></div><div class="g"><label class="f w"><span>Placement</span><select id="szfit"><option value="contain" ${st.szfit!=='cover'?'selected':''}>Fit — product colour behind</option><option value="cover" ${st.szfit==='cover'?'selected':''}>Fill — crop to each size</option></select></label></div><label class="cb"><input type="checkbox" id="szmock" ${st.szmock===false?'':'checked'}><span>Add a device mockup for each size</span></label><div class="ex"><button class="btn pri" data-x="allsz">Export all sizes (ZIP)</button></div>`}
const loadImg=src=>new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=rej;im.src=src});
const blobU8=async b=>new Uint8Array(await b.arrayBuffer());
async function exportSizes(e){if(!ARTS[0])return toast('Upload your design in artwork slot 1 first');const im=await loadImg(ARTS[0]).catch(()=>null);if(!im)return toast('That artwork could not be read');
 const iw=im.naturalWidth||1000,ih=im.naturalHeight||1000,sel=DSZ.filter((_,i)=>!(st.szoff||[]).includes(i));if(!sel.length)return toast('Tick at least one size');
 const files=[],mk=st.szmock!==false;let k=0;for(const[n,p]of sel){k++;toast(`Rendering ${k} of ${sel.length} — ${n}`);const c=document.createElement('canvas');c.width=p.w;c.height=p.h;const x=c.getContext('2d');x.fillStyle=st.mo.brand;x.fillRect(0,0,p.w,p.h);
  const s=st.szfit==='cover'?Math.max(p.w/iw,p.h/ih):Math.min(p.w/iw,p.h/ih)*(1-2*(p.safe||5)/100);x.drawImage(im,(p.w-iw*s)/2,(p.h-ih*s)/2,iw*s,ih*s);
  files.push({name:`sizes/${slug(n)}.png`,data:await blobU8(await new Promise(r=>c.toBlob(r,'image/png')))});
  if(mk){const v={...defs('digital'),...p};files.push({name:`mockups/${slug(n)}_mockup.png`,data:await blobU8(await toPng(productSvg('digital',v,pmo(),true),1600,1120))})}}
 files.push({name:'README.txt',data:`ALL SIZES — ${e.n}\n\nsizes/    your design placed in each platform size (PNG, sRGB, 1x)\n${mk?'mockups/  each size shown on its device\n':''}\nPlacement: ${st.szfit==='cover'?'fill and crop':'fit inside the safe margin, product colour behind'}.\nCheck text near the edges of story and cover sizes: the platform interface covers those zones.\n`});
 save(slug(e.n)+'_all-sizes.zip',zip(files))}

