function itemBoardSvg(e){if(e.b)return boardSvg(e.b,bd(e.b));const key='item:'+e.i,o={...(st.bd[key]||{...bdDefaults('item'),title:e.n,intro:`${IT[e.g].name} · ${(KL[e.k]||KL.dedicated)[0]}`})};o._item={g:e.g,v:vals(e),k:e.k||'dedicated'};return boardSvg('item',o)}
function viewSvg(e,k){const v=vals(e);if(k==='pboard')return itemBoardSvg(e);if(k==='mock')return productSvg(e.g,v,pmo(),true);if(k==='scene')return e.m?mockSvg(e.m,st.mo,true):sceneSvg(e.g,v,pmo(),envOf(e),true);
 const sh=build(e.g,v);if(k==='board')return specBoardSvg(e.i,e.n,e.g,v,sh,validate(e.g,v,sh),prodTxt(v._prod));return svgOf(sh,{exp:1,on:st.on,title:e.n})}
const nest=(svg,x,y,w,h)=>fit(svg).replace(/<\?xml[^>]*>/,'').replace('<svg ',`<svg x="${x}" y="${y}" width="${w}" height="${h}" `);
function glPage(W,H,o,{sec,name,no,body}){const C=o.client||'Brand';return`<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}"><rect width="${W}" height="${H}" fill="#fff"/>`+
 txt(64,70,C.toUpperCase(),{s:15,w:600,c:SG.red,ls:2.2})+txt(W-64,70,sec.toUpperCase(),{s:15,w:600,c:SG.muted,a:'end',ls:2.2})+txt(64,128,name.toUpperCase(),{s:40,w:300,c:SG.ink})+`<rect x="64" y="152" width="${W-128}" height="1" fill="${SG.line}"/>`+
 body+`<rect x="64" y="${H-58}" width="${W-128}" height="1" fill="${SG.line}"/>`+txt(64,H-30,o.title,{s:13,c:SG.muted})+txt(W-64,H-30,String(no).padStart(2,'0'),{s:13,w:600,c:SG.ink,a:'end'})+'</svg>'}
const rasterJpg=(svg,w,h)=>new Promise((res,rej)=>{const im=new Image();im.onload=()=>{const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,w,h);x.drawImage(im,0,0,w,h);c.toBlob(async b=>b?res(await blobU8(b)):rej(),'image/jpeg',.9)};im.onerror=rej;im.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)});
function pdfJpgs(pages,pw,ph,title){const en=new TextEncoder(),ch=[],off=[];let len=0;const put=d=>{const b=typeof d==='string'?en.encode(d):d;ch.push(b);len+=b.length};
 const obj=(id,...parts)=>{off[id]=len;put(`${id} 0 obj\n`);parts.forEach(put);put('\nendobj\n')};const n=pages.length,info=3+n*3;
 put('%PDF-1.4\n');put(new Uint8Array([37,226,227,207,211,10]));obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,`<< /Type /Pages /Count ${n} /Kids [${pages.map((_,i)=>`${3+i*3} 0 R`).join(' ')}] >>`);
 pages.forEach((p,i)=>{const pid=3+i*3,cid=pid+1,iid=pid+2,cs=`q ${pw} 0 0 ${ph} 0 0 cm /Im0 Do Q`;
  obj(pid,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pw} ${ph}] /Resources << /XObject << /Im0 ${iid} 0 R >> >> /Contents ${cid} 0 R >>`);
  obj(cid,`<< /Length ${cs.length} >>\nstream\n${cs}\nendstream`);obj(iid,`<< /Type /XObject /Subtype /Image /Width ${p.w} /Height ${p.h} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${p.data.length} >>\nstream\n`,p.data,'\nendstream')});
 obj(info,`<< /Title (${String(title).replace(/[^\x20-\x7e]/g,'').replace(/[()\\]/g,'')}) /Producer (Dieline Lab) >>`);
 const xr=len;put(`xref\n0 ${info+1}\n0000000000 65535 f \n`+off.slice(1).map(o=>String(o).padStart(10,'0')+' 00000 n \n').join('')+`trailer\n<< /Size ${info+1} /Root 1 0 R /Info ${info} 0 R >>\nstartxref\n${xr}\n%%EOF`);
 const out=new Uint8Array(len);let p=0;ch.forEach(b=>{out.set(b,p);p+=b.length});return out}
async function exportGuideline(){const o=glo(),items=(st.gl||[]).map(i=>BYID[i]).filter(Boolean),vs=GLV.filter(([k])=>o.views[k]);if(!items.length||!vs.length)return toast('Add items and tick at least one view');
 const[,pw,ph,px]=GLP[o.size],W=1600,H=Math.round(W*ph/pw),PX=px,PY=Math.round(px*ph/pw),pages=[];let no=1;
 const list=[];items.forEach(e=>vs.forEach(([k,t])=>list.push({e,k,t})));
 const total=list.length+2;const add=async svg=>{toast(`Building page ${pages.length+1} of ${total}`);pages.push({w:PX,h:PY,data:await rasterJpg(svg,PX,PY)})};
 try{useArts(null);const logo=GART[0];
  await add(`<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}"><rect width="${W}" height="${H}" fill="#fff"/><rect x="64" y="64" width="18" height="18" fill="${SG.red}"/>`+(logo?`<image href="${logo}" xlink:href="${logo}" x="64" y="${H*.16}" width="420" height="${H*.24}" preserveAspectRatio="xMinYMid meet"/>`:'')+txt(64,H*.62,(o.client||'Brand').toUpperCase(),{s:20,w:600,c:SG.red,ls:3})+txt(64,H*.62+84,o.title.toUpperCase(),{s:64,w:300,c:SG.ink})+txt(64,H-64,`${items.length} applications · ${new Date().toLocaleDateString('en-GB',{month:'long',year:'numeric'})}`,{s:16,c:SG.muted})+'</svg>');no++;
  let pg=3,rows='';items.forEach((e,i)=>{if(i<22)rows+=txt(64+(i>10?760:0),230+(i%11)*58,String(i+1).padStart(2,'0'),{s:15,w:600,c:SG.red})+txt(120+(i>10?760:0),230+(i%11)*58,e.n,{s:22,c:SG.ink})+txt(760+(i>10?760:0)-40,230+(i%11)*58,'p. '+pg,{s:15,c:SG.muted,a:'end'});pg+=vs.length});
  await add(glPage(W,H,o,{sec:'Contents',name:'Applications',no:no++,body:rows}));
  for(const{e,k,t}of list){useArts(e);let sv;try{sv=viewSvg(e,k)}catch(er){sv=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 200"><text x="20" y="100">This view could not be drawn with the current values.</text></svg>`}
   await add(glPage(W,H,o,{sec:t,name:e.n,no:no++,body:nest(sv,64,176,W-128,H-176-80)}))}
  useArts(ctxItem());save(slug(o.client||'brand')+'_'+slug(o.title)+'.pdf',pdfJpgs(pages,pw,ph,o.title))}catch(er){useArts(ctxItem());toast('The PDF could not be built here: '+(er&&er.message||'render error'))}}

